	public static int GetPow(string jsr)
	{
		string mainChunk = jsr.Split('-')[0];
		int next = 2;
		int a = 0;
		string u = "";
		for (int i = 0; i < 10000; i++)
		{
			switch (next)
			{
			case 2:
				a++;
				u = CreateMD5(mainChunk + a);
				if (a % 1000 != 0)
				{
					next = 8;
				}
				break;
			case 8:
				if (u.Substring(0, 2) != "00")
				{
					next = 2;
					break;
				}
				return a;
			}
		}
		return -1;
	}

	private static void UpdateJsid(string url, string userAgent, string data, WebProxy proxy)
	{
		DateTime start = DateTime.Now;
		bool isReady = false;
		Uri uri = new Uri(url);
		string proxy_host = null;
		int proxy_port = -1;
		string proxy_username = null;
		string proxy_password = null;
		if (proxy != null)
		{
			proxy_host = proxy.Address.Host;
			proxy_port = proxy.Address.Port;
			if (proxy.Credentials != null)
			{
				proxy_username = ((NetworkCredential)proxy.Credentials).UserName;
				proxy_password = ((NetworkCredential)proxy.Credentials).Password;
			}
		}
		ExtendedTcpClient client = new ExtendedTcpClient(uri.Host, 443, isSecure: true, uri.Host, proxy_host, proxy_port, proxy_username, proxy_password);
		client.OnDataReceived += delegate(byte[] responseData)
		{
			string text = Net.Parse(Encoding.UTF8.GetString(responseData), "Set-Cookie: ", ";");
			if (text != "")
			{
				string text2 = text.Split('=')[0];
				string value = text.Replace(text2 + "=", "");
				cookieContainer.Add(uri, new Cookie(text2, value, "/", uri.Host));
			}
			client.Close();
			isReady = true;
		};
		client.Connect();
		string cookie = cookieContainer.GetCookies(uri)[0].ToString();
		string request = "POST " + url + " HTTP/1.1\r\nHost: " + uri.Host + "\r\nConnection: keep-alive\r\nContent-Length: " + data.Length + "\r\nPragma: no-cache\r\nCache-Control: no-cache\r\nsec-ch-ua: " + sec_ch_ua + "\r\nsec-ch-ua-platform: \"Windows\"\r\nsec-ch-ua-mobile: ?0\r\nUser-Agent: " + userAgent + "\r\nContent-Type: application/json\r\nAccept: */*\r\nOrigin: https://" + uri.Host + "\r\nSec-Fetch-Site: same-origin\r\nSec-Fetch-Mode: cors\r\nSec-Fetch-Dest: empty\r\nAccept-Encoding: gzip, deflate, br, zstd\r\nAccept-Language: ru-RU,ru;q=0.9,en-US;q=0.8,en;q=0.7\r\nCookie: " + cookie + "\r\n\r\n" + data;
		client.Send(Encoding.UTF8.GetBytes(request));
		while (!isReady && (DateTime.Now - start).TotalMilliseconds < 5000.0)
		{
			Thread.Sleep(50);
		}
	}

	private static string CreateMD5(string input)
	{
		using MD5 md5 = MD5.Create();
		byte[] inputBytes = Encoding.ASCII.GetBytes(input);
		byte[] hashBytes = md5.ComputeHash(inputBytes);
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < hashBytes.Length; i++)
		{
			sb.Append(hashBytes[i].ToString("x2"));
		}
		return sb.ToString();
	}

	private static long GetTimestamp()
	{
		return (long)DateTime.UtcNow.Subtract(new DateTime(1970, 1, 1)).TotalMilliseconds;
	}

	private static string Encode(string data, string jsr, int pow)
	{
		Random random = new Random();
		string rand = "";
		for (int i = 0; i < 4; i++)
		{
			rand += HEX[random.Next(0, 15)];
		}
		string dateCode = jsr.Split('-')[0];
		string hash = CreateMD5(rand + dateCode + pow);
		string encodedString = "";
		for (int j = 0; j < data.Length; j++)
		{
			encodedString += (char)(data[j] ^ hash[j % 32]);
		}
		return "v1$" + rand + "$" + Btoa(encodedString);
	}

	public static string Decode(string data, string jsr, int pow)
	{
		string[] array = data.Split('$');
		string rand = array[1];
		string input = array[2];
		string result = "";
		string atobDecoded = Atob(input);
		string dateCode = jsr.Split('-')[0];
		string hash = CreateMD5(rand + dateCode + pow);
		for (int i = 0; i < atobDecoded.Length; i++)
		{
			result += (char)(atobDecoded[i] ^ hash[i % 32]);
		}
		return result;
	}

	private static string Btoa(string input)
	{
		return Convert.ToBase64String(Encoding.GetEncoding(28591).GetBytes(input));
	}

	private static string Atob(string input)
	{
		byte[] data = Convert.FromBase64String(input);
		return Encoding.GetEncoding(28591).GetString(data);
	}

	private static string GETResponse_1(string url, string userAgent, WebProxy proxy = null)
	{
		HttpWebRequest request = (HttpWebRequest)WebRequest.Create(url);
		request.Method = "GET";
		request.Accept = "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.7";
		request.Headers.Add("Cache-Control: no-cache");
		request.Headers.Add("Pragma: no-cache");
		request.Headers.Add("Accept-Encoding: gzip, deflate, br, zstd");
		request.Headers.Add("Accept-Language: ru-RU,ru;q=0.9,en-US;q=0.8,en;q=0.7");
		request.Headers.Add("sec-ch-ua: " + sec_ch_ua);
		request.Headers.Add("sec-ch-ua-mobile: ?0");
		request.Headers.Add("Sec-Fetch-Dest: document");
		request.Headers.Add("Sec-Fetch-Mode: navigate");
		request.Headers.Add("sec-ch-ua-platform: \"Windows\"");
		request.Headers.Add("Sec-Fetch-Site: none");
		request.Headers.Add("Sec-Fetch-User: ?1");
		request.Headers.Add("Upgrade-Insecure-Requests: 1");
		request.UserAgent = userAgent;
		request.CookieContainer = cookieContainer;
		request.AutomaticDecompression = DecompressionMethods.GZip;
		request.KeepAlive = true;
		if (proxy != null)
		{
			request.Proxy = proxy;
		}
		request.ContinueTimeout = 5000;
		string result = "";
		try
		{
			WebResponse response = request.GetResponse();
			result = new StreamReader(response.GetResponseStream()).ReadToEnd();
			response.Close();
		}
		catch (Exception ex)
		{
			result = ex.ToString();
		}
		return result;
	}

