	private static string POSTResponse(string url, string userAgent, string data, WebProxy proxy = null)
	{
		HttpWebRequest request = (HttpWebRequest)WebRequest.Create(url);
		request.Method = "POST";
		request.UserAgent = userAgent;
		request.Accept = "*/*";
		request.Headers.Add("Cache-Control: no-cache");
		request.Headers.Add("Pragma: no-cache");
		request.Headers.Add("Accept-Language: ru-RU,ru;q=0.9,en-US;q=0.8,en;q=0.7");
		request.Headers.Add("Accept-Encoding: gzip, deflate, br, zstd");
		request.Headers.Add("Origin: https://" + new Uri(url).Host);
		request.Headers.Add("sec-ch-ua: \"Google Chrome\";v=\"125\", \"Chromium\";v=\"125\", \"Not.A/Brand\";v=\"24\"");
		request.Headers.Add("sec-ch-ua-mobile: ?0");
		request.Headers.Add("Sec-Fetch-Dest: empty");
		request.Headers.Add("Sec-Fetch-Mode: cors");
		request.Headers.Add("sec-ch-ua-platform: \"Windows\"");
		request.Headers.Add("Sec-Fetch-Site: same-origin");
		request.CookieContainer = cookieContainer;
		request.ContentType = "application/json";
		request.KeepAlive = true;
		if (proxy != null)
		{
			request.Proxy = proxy;
		}
		request.AutomaticDecompression = DecompressionMethods.GZip;
		string result = "";
		try
		{
			request.GetRequestStream().Write(Encoding.UTF8.GetBytes(data), 0, data.Length);
			WebResponse response = request.GetResponse();
			result = new StreamReader(response.GetResponseStream()).ReadToEnd();
			response.Close();
		}
		catch (Exception ex)
		{
			result = "@ERROR:" + ex.Message;
		}
		return result;
	}
